S = "Hakeem Force Academy"
QS = [
(S, "In aviation and avionics, in which unit is altitude commonly measured?", ["Feet", "Knots", "Degrees", "Pascals per second"], 0, "Altitude of an aircraft is reported in feet in most of the world's civil aviation. Speed is given in knots, not altitude.", "Some countries, such as China and Russia, use metres for altitude in parts of their airspace.", [628]),
(S, "Why did the United States enter World War II in December 1941?", ["Japan attacked its naval base at Pearl Harbor", "Germany invaded Poland", "Italy attacked Britain", "Russia attacked Finland"], 0, "Japan carried out a surprise air attack on Pearl Harbor, Hawaii, on 7 December 1941. The US declared war on Japan the next day.", "Germany and Italy then declared war on the United States a few days later.", [1451]),
(S, "What is the spread of cultural traits from one society to another called?", ["Cultural diffusion", "Cultural diversity", "Cultural lag", "Ethnocentrism"], 0, "Cultural diffusion is the transfer of ideas, customs and technology from one society to another. Cultural diversity only means many cultures exist together.", "Cultural lag means material culture changes faster than beliefs and values.", [1040]),
(S, "How did Quaid-e-Azam Muhammad Ali Jinnah respond to the Nehru Report of 1928?", ["He rejected it and later presented his Fourteen Points", "He accepted it fully", "He asked the British to enforce it", "He ignored it and left politics"], 0, "The Nehru Report did not protect Muslim rights such as separate electorates, so Jinnah rejected it. In 1929 he gave his Fourteen Points as the Muslim demands.", "Jinnah's earlier Delhi Muslim Proposals of 1927 had been turned down by the Congress.", [153]),
(S, "What is the antonym of 'delight'?", ["Joy", "Pleasure", "Sorrow", "Glee"], 2, "Delight means great pleasure, so its opposite is sorrow or misery. The other options are synonyms.", "Another opposite of delight is displeasure.", [914]),
(S, "What is the antonym of 'fragile'?", ["Delicate", "Sturdy", "Brittle", "Weak"], 1, "Fragile means easily broken, so the opposite is sturdy or strong. Delicate, brittle and weak are close in meaning to fragile.", "The word fragile comes from the Latin fragilis, meaning easily broken.", [361]),
(S, "What is the antonym of 'secret'?", ["Hidden", "Private", "Covert", "Public"], 3, "Secret means kept hidden from others, so the opposite is public or open. The other options are synonyms.", "Overt is another opposite of secret in formal English.", [362]),
(S, "What is the antonym of 'terrifying'?", ["Frightening", "Comforting", "Horrifying", "Alarming"], 1, "Terrifying means causing great fear, so the opposite is comforting or soothing. The others are synonyms.", "Reassuring is another good opposite of terrifying.", [916]),
(S, "What is the antonym of 'condensed'?", ["Compressed", "Shortened", "Expanded", "Concise"], 2, "Condensed means made shorter or more compact, so the opposite is expanded. The other options mean the same as condensed.", "In science, condensation is the change of a gas into a liquid.", [918]),
(S, "What is the antonym of 'idleness'?", ["Laziness", "Industry", "Rest", "Sloth"], 1, "Idleness means doing no work, so the opposite is industry, meaning hard work. Laziness and sloth are synonyms.", "The proverb says an idle mind is the devil's workshop.", [921]),
(S, "The Arabian Sea is a part of which ocean?", ["Atlantic Ocean", "Indian Ocean", "Pacific Ocean", "Arctic Ocean"], 1, "The Arabian Sea is the north-western part of the Indian Ocean. It lies between India, Pakistan, Iran and the Arabian Peninsula.", "Pakistan's coastline along the Arabian Sea is about 1000 kilometres long.", [790]),
(S, "On which date did East Pakistan become Bangladesh after the fall of Dhaka?", ["14 August 1971", "16 December 1971", "26 March 1972", "23 March 1971"], 1, "Pakistani forces in East Pakistan surrendered on 16 December 1971, and Bangladesh came into being. This date is observed as Fall of Dhaka Day.", "Bangladesh declared independence on 26 March 1971, before the surrender.", [1109]),
(S, "The separation of Bangladesh in 1971 benefited which neighbouring country the most?", ["India", "China", "Iran", "Afghanistan"], 0, "India supported the separation and fought the 1971 war, which weakened its rival Pakistan. India therefore gained strategically.", "The 1971 war ended with the surrender of about 90000 Pakistani personnel.", [802]),
(S, "What does ADB stand for?", ["Asian Development Bank", "African Development Bank", "American Defence Bureau", "Arab Deposit Bank"], 0, "ADB is the Asian Development Bank, which lends money to Asian countries for development. Pakistan is one of its members.", "The ADB headquarters is in Manila, Philippines.", [838]),
(S, "What is the logarithm of a number to its own base?", ["0", "1", "10", "The number itself"], 1, "By definition, log base a of a equals 1 because a raised to the power 1 is a. For example, log 10 to base 10 is 1.", "The logarithm of 1 to any base is 0.", [980]),
(S, "What is the logarithm of unity (1) to any base?", ["1", "Undefined", "Infinity", "0"], 3, "Any base raised to the power 0 gives 1, so log of 1 to any base is 0.", "The logarithm of a negative number is not defined in real numbers.", [160]),
(S, "Arrange the letters of TEYUAB to make a word. What is the last letter of the word?", ["B", "T", "E", "Y"], 3, "The letters T, E, Y, U, A, B make the word BEAUTY. Its last letter is Y.", "Beauty is a noun meaning pleasing quality.", [204, 974]),
(S, "Arrange the letters of PLOEADR to make the name of an animal.", ["Leopard", "Pelorad", "Dolphin", "Panther"], 0, "The letters P, L, O, E, A, D, R make the word LEOPARD, a big cat. It uses all seven letters once.", "The leopard is a spotted big cat found in Asia and Africa.", [824]),
(S, "Under the 1973 Constitution of Pakistan, who is the head of government?", ["The President", "The Prime Minister", "The Chief Justice", "The Speaker of the National Assembly"], 1, "Pakistan has a parliamentary system. The Prime Minister heads the government and the President is the head of state.", "The Prime Minister is elected by the National Assembly.", [632]),
(S, "Who wrote the book 'Friends, Not Masters'?", ["Zulfikar Ali Bhutto", "Field Marshal Ayub Khan", "Liaquat Ali Khan", "General Zia-ul-Haq"], 1, "Friends, Not Masters is the political autobiography of Ayub Khan, published in 1967. It describes his view of Pakistan's relations with great powers.", "Zulfikar Ali Bhutto wrote The Myth of Independence.", [1339]),
(S, "About how many litres of blood does an average adult human body contain?", ["2 litres", "3 litres", "5 litres", "8 litres"], 2, "An average adult has about 5 litres of blood, which is roughly 7 to 8 percent of body weight.", "Blood is pumped around the body by the heart.", [923]),
(S, "Peshawar is associated with which ancient civilisation?", ["Gandhara", "Indus Valley", "Mehrgarh", "Mesopotamia"], 0, "Peshawar, once called Purushapura, was a capital of the Gandhara civilisation in Kushan times. Gandhara art blended Greek and Buddhist styles.", "Taxila was another important Gandhara city.", [283]),
(S, "Choose the correct sentence.", ["The Principal has accepted my application.", "The Principal have accepted my application.", "The Principal has accept my application.", "The Principal accepting my application."], 0, "Principal is singular, so it takes has, and the present perfect needs the past participle accepted.", "Principal means head of a school, while principle means a rule.", [487, 515]),
(S, "On which date of Ramadan was the Battle of Badr fought?", ["1 Ramadan", "10 Ramadan", "17 Ramadan", "27 Ramadan"], 2, "The Battle of Badr took place on 17 Ramadan, 2 AH, which is March 624 CE.", "It is also called Youm-e-Furqan.", [757]),
(S, "Rahman Baba was a famous poet of which language?", ["Punjabi", "Sindhi", "Pashto", "Balochi"], 2, "Rahman Baba was a 17th century Sufi poet of Peshawar who wrote in Pashto. His shrine is near Peshawar.", "His collection of poems is called Diwan.", [773]),
(S, "How many population censuses had Pakistan held up to the 2023 census, including it?", ["5", "6", "7", "8"], 2, "Censuses were held in 1951, 1961, 1972, 1981, 1998, 2017 and 2023, which makes seven.", "The 2023 census was the first fully digital census of Pakistan.", [553]),
(S, "In which region of Asia is Pakistan located?", ["Central Asia", "South Asia", "East Asia", "South-East Asia"], 1, "Pakistan lies in the north-west of South Asia. It borders Iran, Afghanistan, China and India.", "Pakistan is a member of SAARC.", [979]),
(S, "Which is the longest river of Asia?", ["Yangtze", "Indus", "Ganges", "Mekong"], 0, "The Yangtze in China is about 6300 km long and is the longest river in Asia. The Indus is about 3200 km long.", "The Yangtze is the third longest river in the world.", [927]),
]
